import { Link, useNavigate } from "react-router-dom";
import { useState } from "react";

export default function Menu({ usuarioLogueado, setUsuarioLogueado }) {
  const navigate = useNavigate();

  const handleLogout = () => {
    setUsuarioLogueado(null);
    localStorage.removeItem("token");
    navigate("/login");
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-dark bg-dark mb-4">
      <div className="container-fluid">
        <Link className="navbar-brand" to="/">Mi aplicación</Link>

        <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#menu">
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className="collapse navbar-collapse" id="menu">
          <ul className="navbar-nav me-auto">

            <li className="nav-item">
              <Link className="nav-link" to="/">Inicio</Link>
            </li>

            <li className="nav-item">
              <Link className="nav-link" to="/incidencias">Ver incidencias</Link>
            </li>

            <li className="nav-item">
              <Link className="nav-link" to="/registrar">Registrar incidencia</Link>
            </li>

            {usuarioLogueado?.rol === "admin" && (
              <li className="nav-item">
                <Link className="nav-link" to="/usuarios">Gestión usuarios</Link>
              </li>
            )}

          </ul>

          {usuarioLogueado && (
            <button className="btn btn-outline-light" onClick={handleLogout}>
              Cerrar sesión
            </button>
          )}
        </div>
      </div>
    </nav>
  );
}
